'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency, formatDate } from '@/lib/utils';
import { 
  UserIcon, 
  PlusIcon, 
  MagnifyingGlassIcon,
  EnvelopeIcon,
  PhoneIcon,
  MapPinIcon,
  PencilIcon,
  TrashIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { 
  Dialog, 
  DialogContent, 
  DialogDescription, 
  DialogFooter, 
  DialogHeader, 
  DialogTitle, 
  DialogTrigger 
} from '@/components/ui/dialog';
import { useToast } from '@/components/ui/toaster';
import { Label } from '@/components/ui/label';

// Types
interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  address: string;
  totalPurchases: number;
  totalSpent: number;
  lastPurchase: string;
  status: 'active' | 'inactive';
  memberSince: string;
}

const customerStatuses = ['All', 'Active', 'Inactive'];

export default function CustomersPage() {
  const { toast } = useToast();
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  
  // Local state for CRM (mocked backend)
  const [customers, setCustomers] = useState<Customer[]>([
    {
      id: '1',
      name: 'John Smith',
      email: 'john.smith@email.com',
      phone: '+1 (555) 123-4567',
      address: '123 Main St, City, State 12345',
      totalPurchases: 45,
      totalSpent: 2345.67,
      lastPurchase: '2024-03-12T10:30:00Z',
      status: 'active',
      memberSince: '2023-01-15'
    },
    {
      id: '2',
      name: 'Sarah Johnson',
      email: 'sarah.j@email.com',
      phone: '+1 (555) 987-6543',
      address: '456 Oak Ave, Town, State 67890',
      totalPurchases: 28,
      totalSpent: 1567.89,
      lastPurchase: '2024-03-10T14:20:00Z',
      status: 'active',
      memberSince: '2023-03-22'
    }
  ]);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    status: 'active' as 'active' | 'inactive'
  });

  const filteredCustomers = customers.filter(customer => {
    const matchesSearch = customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         customer.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         customer.phone.includes(searchTerm);
    const matchesStatus = statusFilter === 'All' || customer.status === statusFilter.toLowerCase();
    return matchesSearch && matchesStatus;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCustomer) {
      setCustomers(prev => prev.map(c => c.id === editingCustomer.id ? { ...c, ...formData } : c));
      toast({ title: 'Updated', description: 'Customer details updated successfully' });
    } else {
      const newCustomer: Customer = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        totalPurchases: 0,
        totalSpent: 0,
        lastPurchase: new Date().toISOString(),
        memberSince: new Date().toLocaleDateString('en-CA'),
        status: formData.status as 'active' | 'inactive'
      };
      setCustomers(prev => [...prev, newCustomer]);
      toast({ title: 'Success', description: 'New customer added successfully' });
    }
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({ name: '', email: '', phone: '', address: '', status: 'active' });
    setEditingCustomer(null);
  };

  const handleEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      name: customer.name,
      email: customer.email,
      phone: customer.phone,
      address: customer.address,
      status: customer.status
    });
    setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to remove this customer record?')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
      toast({ title: 'Deleted', description: 'Customer record removed' });
    }
  };

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Customers Header */}
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-primary">Customer Relationship Management</h1>
              <p className="text-sm text-text-secondary">Track purchase history and loyalty memberships</p>
            </div>
            
            <Dialog open={isModalOpen} onOpenChange={(open) => { if (!open) { setIsModalOpen(false); resetForm(); } }}>
              <DialogTrigger asChild>
                <Button onClick={() => { resetForm(); setIsModalOpen(true); }}>
                  <PlusIcon className="h-4 w-4 mr-2" />
                  Add New Customer
                </Button>
              </DialogTrigger>
              <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                  <DialogTitle>{editingCustomer ? 'Edit Customer' : 'Register New Customer'}</DialogTitle>
                  <DialogDescription>Enter the customer's contact details for membership tracking.</DialogDescription>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4 py-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2 col-span-2">
                      <Label htmlFor="name">Full Name</Label>
                      <Input id="name" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="email">Email</Label>
                      <Input id="email" type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="phone">Phone Number</Label>
                      <Input id="phone" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                    </div>
                    <div className="space-y-2 col-span-2">
                      <Label htmlFor="address">Physical Address</Label>
                      <Input id="address" required value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="status">Membership Status</Label>
                      <select 
                        id="status" 
                        className="input-field w-full" 
                        value={formData.status} 
                        onChange={e => setFormData({...formData, status: e.target.value as 'active' | 'inactive'})}
                      >
                        <option value="active">Active</option>
                        <option value="inactive">Inactive</option>
                      </select>
                    </div>
                  </div>
                  <DialogFooter>
                    <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit">{editingCustomer ? 'Save Changes' : 'Register Customer'}</Button>
                  </DialogFooter>
                </form>
              </DialogContent>
            </Dialog>
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-primary/10 rounded-lg"><UserGroupIcon className="h-6 w-6 text-primary" /></div>
                <div className="ml-4">
                  <p className="text-xs font-medium text-text-secondary uppercase tracking-wider">Total CRM Base</p>
                  <p className="text-2xl font-bold text-primary">{customers.length}</p>
                </div>
              </div>
            </div>
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-success/10 rounded-lg"><UserIcon className="h-6 w-6 text-success" /></div>
                <div className="ml-4">
                  <p className="text-xs font-medium text-text-secondary uppercase tracking-wider">Active Members</p>
                  <p className="text-2xl font-bold text-success">{customers.filter(c => c.status === 'active').length}</p>
                </div>
              </div>
            </div>
            <div className="card p-6 border-l-4 border-info">
              <div className="flex items-center">
                <div className="ml-4">
                  <p className="text-xs font-medium text-text-secondary uppercase tracking-wider">Avg. Spend</p>
                  <p className="text-2xl font-bold text-primary">{formatCurrency(1950.28)}</p>
                </div>
              </div>
            </div>
            <div className="card p-6 border-l-4 border-warning">
              <div className="flex items-center">
                <div className="ml-4">
                  <p className="text-xs font-medium text-text-secondary uppercase tracking-wider">Loyalty Growth</p>
                  <p className="text-2xl font-bold text-primary">+12.5%</p>
                </div>
              </div>
            </div>
          </div>

          {/* Search and Filters */}
          <div className="card p-4">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <Input
                    placeholder="Search by name, email or phone..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10"
                  />
                </div>
              </div>
              <div className="flex gap-2">
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="input-field"
                >
                  {customerStatuses.map(status => (
                    <option key={status} value={status}>{status}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Customers Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredCustomers.length > 0 ? filteredCustomers.map(customer => (
              <div key={customer.id} className="card p-6 hover-lift border-t-2 border-transparent hover:border-primary/50 transition-all">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center space-x-3">
                    <div className="h-12 w-12 bg-surface rounded-xl flex items-center justify-center border border-divider">
                      <UserIcon className="h-6 w-6 text-primary" />
                    </div>
                    <div>
                      <h3 className="font-bold text-primary text-lg leading-tight">{customer.name}</h3>
                      <Badge variant={customer.status === 'active' ? 'success' : 'secondary'}>
                        {customer.status}
                      </Badge>
                    </div>
                  </div>
                  <div className="flex space-x-1">
                    <Button variant="ghost" size="icon" onClick={() => handleEdit(customer)} className="hover:bg-info/10 hover:text-info">
                      <PencilIcon className="h-4 w-4" />
                    </Button>
                    <Button variant="ghost" size="icon" onClick={() => handleDelete(customer.id)} className="hover:bg-error/10 hover:text-error">
                      <TrashIcon className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
                
                <div className="space-y-2 text-sm">
                  <div className="flex items-center space-x-3 text-text-secondary">
                    <div className="h-7 w-7 bg-surface rounded-full flex items-center justify-center"><EnvelopeIcon className="h-3.5 w-3.5" /></div>
                    <span className="font-medium">{customer.email}</span>
                  </div>
                  <div className="flex items-center space-x-3 text-text-secondary">
                    <div className="h-7 w-7 bg-surface rounded-full flex items-center justify-center"><PhoneIcon className="h-3.5 w-3.5" /></div>
                    <span className="font-medium">{customer.phone}</span>
                  </div>
                  <div className="flex items-center space-x-3 text-text-secondary">
                    <div className="h-7 w-7 bg-surface rounded-full flex items-center justify-center"><MapPinIcon className="h-3.5 w-3.5" /></div>
                    <span className="truncate font-medium">{customer.address}</span>
                  </div>
                </div>
                
                <div className="border-t border-divider pt-4 mt-6">
                  <div className="grid grid-cols-2 gap-y-4 gap-x-2">
                    <div>
                      <p className="text-[10px] uppercase font-bold text-text-secondary mb-1">Total Orders</p>
                      <p className="font-bold text-primary">{customer.totalPurchases}</p>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-text-secondary mb-1">Lifetime Value</p>
                      <p className="font-bold text-primary">{formatCurrency(customer.totalSpent)}</p>
                    </div>
                    <div className="col-span-2">
                      <p className="text-[10px] uppercase font-bold text-text-secondary mb-1">Member Since</p>
                      <p className="text-xs font-semibold text-primary">{customer.memberSince}</p>
                    </div>
                  </div>
                  <div className="mt-4">
                    <Button variant="outline" size="sm" className="w-full text-xs font-bold uppercase tracking-widest h-10 border-primary/20 text-primary hover:bg-primary/5">
                      Purchase History
                    </Button>
                  </div>
                </div>
              </div>
            )) : (
              <div className="col-span-full card py-20 text-center">
                <UserGroupIcon className="h-20 w-20 mx-auto text-text-secondary opacity-20 mb-4" />
                <h3 className="text-xl font-bold text-primary">No Customers Found</h3>
                <p className="text-text-secondary">Try adjusting your search or filters</p>
              </div>
            )}
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
